pair A,B,C,D,X,Y;
A=dir(100)*(20,0);
B=dir(40)*(20,0);
C=dir(200)*(20,0);
D=dir(320)*(20,0);
X=dir(80)*(20,0);
Y=dir(280)*(20,0);
draw(circle((0,0),20));
draw(A--B);
draw(C--D);
draw(X--Y);
